// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.k8sdump;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class K8sHeapDumpDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MemoryBreakdown breakdown = new MemoryBreakdown();
        breakdown.report("startup");

        log.info(() -> "Flags that preserve evidence in Kubernetes:");
        log.info(() -> "  -XX:+HeapDumpOnOutOfMemoryError");
        log.info(() -> "  -XX:HeapDumpPath=/var/dumps   (MOUNTED PVC, not /tmp)");
        log.info(() -> "  terminationGracePeriodSeconds: 120 (dump finishes writing)");
        log.info(() -> "  -Xmx / MaxRAMPercentage BELOW the container limit (headroom)");

        log.info(() -> "Distinguish failures:");
        log.info(() -> "  Java heap OOM  → logs show 'OutOfMemoryError: Java heap space' + dump written");
        log.info(() -> "  K8s OOMKilled  → kubectl describe pod: Reason=OOMKilled, exit 137; often NO dump");

        // Demonstrate a Java HEAP OutOfMemoryError (not an OOMKilled).
        // Run with a small -Xmx to see it trigger the heap dump on OOM.
        if (args.length > 0 && args[0].equals("--force-heap-oom")) {
            List<byte[]> hog = new ArrayList<>();
            try {
                while (true) hog.add(new byte[10 * 1024 * 1024]); // 10MB chunks
            } catch (OutOfMemoryError e) {
                log.severe(() -> "Java heap OOM caught: " + e.getMessage()
                        + " (heap dump written to -XX:HeapDumpPath)");
            }
        }
        breakdown.report("before exit");
    }
}

// ─── Would be in MemoryBreakdown.java (heap vs non-heap to explain OOMKilled) ───
class MemoryBreakdown {
    private static final Logger log = Logger.getLogger("BankLog");
    private final java.lang.management.MemoryMXBean mem =
            java.lang.management.ManagementFactory.getMemoryMXBean();

    void report(String phase) {
        var heap = mem.getHeapMemoryUsage();
        var nonHeap = mem.getNonHeapMemoryUsage();
        long heapMb = heap.getUsed() / (1024 * 1024);
        long nonHeapMb = nonHeap.getUsed() / (1024 * 1024);
        // OOMKilled risk = heap + non-heap + direct + stacks > container limit,
        // even when heap alone is well under -Xmx.
        log.info(() -> "[" + phase + "] HEAP=" + heapMb + "MB, NON-HEAP=" + nonHeapMb
                + "MB (Metaspace+CodeCache). Container counts BOTH + direct + stacks.");
    }
}
